const headers = $json.headers ?? {};
const getHeader = (name) => {
  const wanted = name.toLowerCase();
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === wanted);
  return key ? String(headers[key] ?? '') : '';
};
const constantTimeEqual = (left, right) => {
  left = String(left ?? '');
  right = String(right ?? '');
  let diff = left.length ^ right.length;
  const length = Math.max(left.length, right.length);
  for (let i = 0; i < length; i++) diff |= (left.charCodeAt(i) || 0) ^ (right.charCodeAt(i) || 0);
  return diff === 0;
};
const providedSignature = getHeader('x-wc-webhook-signature');
const computedSignature = String($json.computed_signature ?? '');
const signatureValid = providedSignature.length > 0 && computedSignature.length > 0 && constantTimeEqual(providedSignature, computedSignature);
const body = $json.body;
const errors = [];
if (!body || typeof body !== 'object' || Array.isArray(body)) errors.push('body_not_object');
if (body && (body.id === undefined || body.id === null || String(body.id) === '')) errors.push('order_id_missing');
if (body && (!body.status || typeof body.status !== 'string')) errors.push('order_status_missing');
if (body && (typeof body.currency !== 'string' || !/^[A-Za-z]{3}$/.test(body.currency))) errors.push('currency_invalid');
if (body && (body.total === undefined || body.total === null || body.total === '' || !Number.isFinite(Number(body.total)) || Number(body.total) < 0)) errors.push('total_invalid');
if (body && !Array.isArray(body.line_items)) errors.push('line_items_invalid');
if (body && !(body.date_modified_gmt || body.date_created_gmt || body.date_modified || body.date_created)) errors.push('event_time_missing');
const topic = getHeader('x-wc-webhook-topic');
const resource = getHeader('x-wc-webhook-resource');
const event = getHeader('x-wc-webhook-event');
const webhookId = getHeader('x-wc-webhook-id');
const deliveryId = getHeader('x-wc-webhook-delivery-id');
const sourceHeader = getHeader('x-wc-webhook-source');
if (!topic || !resource || !event || !webhookId || !deliveryId || !sourceHeader) errors.push('required_woo_headers_missing');
if (resource && resource !== 'order') errors.push('resource_not_order');
if (topic && !topic.startsWith('order.')) errors.push('topic_not_order');
let sourceSite = '';
try { sourceSite = new URL(sourceHeader).host.toLowerCase(); } catch { errors.push('source_invalid'); }
return {
  json: {
    body,
    payload_sha256: String($json.payload_sha256 ?? ''),
    intake: {
      signature_valid: signatureValid,
      payload_valid: errors.length === 0,
      validation_errors: errors,
      topic, resource, event, webhook_id: webhookId, delivery_id: deliveryId, source_site: sourceSite,
      received_at: new Date().toISOString(),
      n8n_execution_id: String($execution.id ?? '')
    }
  }
};

const body = $json.body;
const intake = $json.intake;
const PREFIX_RULES = [
  { family: 'course', prefixes: ['COURSE-'] },
  { family: 'membership', prefixes: ['MEMBER-', 'SUB-'] },
  { family: 'service', prefixes: ['SERVICE-', 'COACH-'] },
];
const classify = (sku) => {
  const normalized = String(sku ?? '').trim().toUpperCase();
  const rule = PREFIX_RULES.find((candidate) => candidate.prefixes.some((prefix) => normalized.startsWith(prefix)));
  return rule?.family ?? 'unmapped';
};
const amount = (value) => Number(Number(value ?? 0).toFixed(2));
const metaData = Array.isArray(body.meta_data) ? body.meta_data : [];
const metaValue = (key) => {
  const item = metaData.find((candidate) => candidate && candidate.key === key);
  return item && ['string', 'number'].includes(typeof item.value) ? String(item.value) : '';
};
const correlationId = metaValue('_budly_commerce_correlation_id');
const conversationId = metaValue('_budly_conversation_id');
const decisionId = metaValue('_budly_decision_id');
const correlationValid = /^sts2_[a-f0-9]{32}$/.test(correlationId)
  && /^(?:conv_[a-z0-9]{12,40}|[a-f0-9-]{36})$/.test(conversationId)
  && /^dec_[a-z0-9]{12,40}$/.test(decisionId);
const commerceCorrelation = correlationValid ? {
  status: 'linked',
  correlation_id: correlationId,
  conversation_id: conversationId,
  decision_id: decisionId,
} : { status: correlationId || conversationId || decisionId ? 'invalid' : 'absent' };
const lineItems = body.line_items.map((line) => ({
  source_line_id: String(line.id ?? ''),
  source_product_id: String(line.product_id ?? ''),
  source_variation_id: line.variation_id ? String(line.variation_id) : null,
  sku: String(line.sku ?? '').trim(),
  quantity: Number(line.quantity ?? 0),
  line_total: amount(line.total),
  line_tax: amount(line.total_tax),
  product_family: classify(line.sku),
}));
const productFamilies = [...new Set(lineItems.map((line) => line.product_family))].sort();
const occurredRaw = body.date_modified_gmt || body.date_created_gmt || body.date_modified || body.date_created;
const occurredAt = /Z$|[+-]\d{2}:?\d{2}$/.test(occurredRaw) ? occurredRaw : `${occurredRaw}Z`;
const identity = ['woocommerce', intake.source_site, intake.topic, intake.event, intake.webhook_id, intake.delivery_id, String(body.id)].join('|');
return {
  json: {
    idempotency_identity: identity,
    revenue_event: {
      schema_version: 'bros.revenue_event.v1',
      source_system: 'woocommerce',
      source_site: intake.source_site,
      source_event_type: intake.topic,
      source_event_id: `${intake.webhook_id}:${intake.delivery_id}`,
      source_webhook_id: intake.webhook_id,
      source_order_id: String(body.id),
      source_order_number: String(body.number ?? body.id),
      occurred_at: new Date(occurredAt).toISOString(),
      received_at: intake.received_at,
      order_status: String(body.status).toLowerCase(),
      currency: String(body.currency).toUpperCase(),
      gross_amount: amount(body.total),
      discount_amount: amount(body.discount_total),
      shipping_amount: amount(body.shipping_total),
      tax_amount: amount(body.total_tax),
      product_families: productFamilies,
      line_items: lineItems,
      commerce_correlation: commerceCorrelation,
      payload_sha256: $json.payload_sha256,
      mapping_version: 'bros-product-family-map-v1',
      n8n_execution_id: intake.n8n_execution_id
    }
  }
};

const statusCode = Number($json.statusCode ?? 0);
const body = $json.body ?? $json;
const result = Array.isArray(body) ? body[0] : body;
const accepted = statusCode >= 200 && statusCode < 300 && result?.status === 'accepted';
const duplicate = statusCode >= 200 && statusCode < 300 && result?.status === 'duplicate';
if (accepted) return { json: { http_status: 202, response: { ok: true, status: 'accepted', event_id: result.event_id, idempotency_key: result.idempotency_key } } };
if (duplicate) return { json: { http_status: 200, response: { ok: true, status: 'duplicate', event_id: result.event_id, idempotency_key: result.idempotency_key } } };
const log = { severity: 'error', component: 'rev_woo_order_event_intake', stage: 'persistence', code: 'supabase_persistence_failed', n8n_execution_id: String($execution.id ?? ''), upstream_status: statusCode || null, timestamp: new Date().toISOString() };
console.error(JSON.stringify(log));
return { json: { http_status: 503, response: { ok: false, status: 'persistence_failure' } } };

const intake = $json.intake ?? {};
console.error(JSON.stringify({ severity: 'warn', component: 'rev_woo_order_event_intake', stage: 'authentication', code: 'invalid_signature', source_site: intake.source_site || null, webhook_id: intake.webhook_id || null, delivery_id: intake.delivery_id || null, n8n_execution_id: String($execution.id ?? ''), timestamp: new Date().toISOString() }));
return { json: { http_status: 401, response: { ok: false, status: 'invalid_signature' } } };

const intake = $json.intake ?? {};
console.error(JSON.stringify({ severity: 'warn', component: 'rev_woo_order_event_intake', stage: 'validation', code: 'malformed_payload', validation_errors: intake.validation_errors ?? ['unknown'], source_site: intake.source_site || null, webhook_id: intake.webhook_id || null, delivery_id: intake.delivery_id || null, n8n_execution_id: String($execution.id ?? ''), timestamp: new Date().toISOString() }));
return { json: { http_status: 422, response: { ok: false, status: 'malformed_payload' } } };
